package br.com.admeclesial.infrastructure.persistence.financeiro; import br.com.admeclesial.domain.financeiro.AlocacaoPagamento; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.math.BigDecimal; import java.util.*; public interface AlocacaoPagamentoRepository extends JpaRepository<AlocacaoPagamento,Long>{ Optional<AlocacaoPagamento> findByUuid(UUID uuid); @Query("select coalesce(sum(a.valor),0) from AlocacaoPagamento a where a.parcelaAPagarId = :parcelaId") BigDecimal sumValorPorParcela(@Param("parcelaId") Long parcelaId); @Query("select coalesce(sum(a.valor),0) from AlocacaoPagamento a where a.pagamentoId = :pagamentoId") BigDecimal sumValorPorPagamento(@Param("pagamentoId") Long pagamentoId); }